  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "Flupentixol, a tricyclic thioxanthene antipsychotic with a piperazine side chain, has a mean oral bioavailability of 55% (range 30-70%), supporting high F for the query's similar tricyclic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Trazodone, a tricyclic antidepressant with a piperazine side chain, has absolute oral bioavailability of 63-91%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Odanacatib, a sulfone-containing drug with a basic amine, has absolute oral bioavailability of 30% at 50 mg fasted and up to 70% at 10 mg, supporting high F for the query's sulfone and basic center.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Vilazodone, containing a carboxamide and basic piperazine, has absolute oral bioavailability of 72% with food, supporting high F for the query's carboxamide and basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Encainide, a basic amine drug, has oral bioavailability of 20-30% in healthy subjects, which is still above the 20% threshold and provides weak supportive evidence.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on close tricyclic antipsychotic analogues (flupentixol, trazodone) with F 30-91% and consistent supportive evidence from sulfone- and carboxamide-containing drugs; no analogue falls below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Potential solubility-limited absorption due to low neutral fraction at physiological pH.",
    "Transporter effects and metabolic stability not assessed."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C53", "C10", "C22", "C07", "C43"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tricyclic antipsychotics/antidepressants"
    }
  ],
  "revision_action": "initial"
}

